use crate::{bytes, raw, CallError, Dispatch, Size};
use std::fmt;

/// A normalized host input. Focus notifications are generated by the tree.
pub enum Input<'text> {
    Key {
        key: raw::NtKeyInput,
        text: &'text str,
    },
    Text(&'text str),
    Paste(&'text str),
    PointerDown(raw::NtPointerInput),
    PointerMove(raw::NtPointerInput),
    PointerUp(raw::NtPointerInput),
    Wheel(raw::NtWheelInput),
    PointerCancel(raw::NtPointerCancel),
    HostCancel(raw::NtCancelReason),
    Resize(Size),
}

impl Input<'_> {
    pub(crate) fn native(&self, at: u64) -> (raw::NtEvent, raw::NtByteView) {
        use raw::NtEvent__bindgen_ty_1 as Data;
        let (kind, data) = match *self {
            Self::Key { key, .. } => (raw::NT_EVENT_KEY, Data { key }),
            Self::Text(text) => (raw::NT_EVENT_TEXT, Data { text: bytes(text) }),
            Self::Paste(text) => (raw::NT_EVENT_PASTE, Data { text: bytes(text) }),
            Self::PointerDown(pointer) => (raw::NT_EVENT_POINTER_DOWN, Data { pointer }),
            Self::PointerMove(pointer) => (raw::NT_EVENT_POINTER_MOVE, Data { pointer }),
            Self::PointerUp(pointer) => (raw::NT_EVENT_POINTER_UP, Data { pointer }),
            Self::Wheel(wheel) => (raw::NT_EVENT_WHEEL, Data { wheel }),
            Self::PointerCancel(pointer_cancel) => {
                (raw::NT_EVENT_POINTER_CANCEL, Data { pointer_cancel })
            }
            Self::HostCancel(reason) => (raw::NT_EVENT_HOST_CANCEL, Data { reason }),
            Self::Resize(resize) => (raw::NT_EVENT_RESIZE, Data { resize }),
        };
        let key_text = match self {
            Self::Key { text, .. } => bytes(text),
            _ => raw::NtByteView {
                data: std::ptr::null(),
                count: 0,
            },
        };
        (raw::NtEvent { kind, at, data }, key_text)
    }
}

#[derive(Default)]
pub struct DispatchPolicy<'keys> {
    pub reserved: &'keys [raw::NtKeyChord],
    pub traverse_focus: bool,
}

impl DispatchPolicy<'_> {
    pub(crate) fn native(&self) -> raw::NtDispatchPolicy {
        raw::NtDispatchPolicy {
            reserved: self.reserved.as_ptr(),
            reserved_count: self.reserved.len(),
            traverse_focus: self.traverse_focus,
        }
    }
}

#[derive(Debug)]
pub struct DispatchError {
    pub cause: CallError,
    /// The delivered portion of an admitted event, even when a callback fails.
    pub delivery: Option<Dispatch>,
}

impl fmt::Display for DispatchError {
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(&self.cause, out)
    }
}

impl std::error::Error for DispatchError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.cause)
    }
}
